def split_horses(n, m, enemy_pairs):
    from collections import defaultdict, deque

    # Create adjacency list for the graph
    adj_list = defaultdict(list)
    for a, b in enemy_pairs:
        adj_list[a].append(b)
        adj_list[b].append(a)

    # Check if it's possible to split the horses
    def is_bipartite(start):
        colors = [-1] * (n + 1)
        queue = deque([start])
        colors[start] = 0  # Start coloring from the first horse

        while queue:
            node = queue.popleft()
            current_color = colors[node]

            for neighbor in adj_list[node]:
                if colors[neighbor] == -1:
                    colors[neighbor] = 1 - current_color
                    queue.append(neighbor)
                elif colors[neighbor] == current_color:
                    return False, None
        return True, colors

    # Try to find a valid bipartition
    for i in range(1, n + 1):
        if adj_list[i]:
            bipartite, colors = is_bipartite(i)
            if not bipartite:
